var i=`0047-makowiec`;var a=`world-0047`;var o=`PL`;var t=`eastern-europe`;var s=10;var r=136;var l={en:`Makowiec`,ua:`Маковий рулет`};var g={en:`A classic dish from Poland, featuring whole cow milk, chicken egg, poppy seeds, raisin. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: цільне коров'яче молоко, куряче яйце, мак, родзинки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`whole-cow-milk`,200,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,90,`g`],[`unsalted-butter`,90,`g`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:14,i:[[`poppy-seeds`,210,`g`],[`whole-cow-milk`,120,`ml`],[`honey`,90,`g`],[`raisin`,75,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 20 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 20 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:20,i:[]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,45,`g`]]}];var d={slug:i,id:a,country:`PL`,region:t,servings:10,minutes:136,title:l,text:g,steps:u};export{o as country,d as default,a as id,r as minutes,t as region,s as servings,i as slug,u as steps,g as text,l as title};